{id:'banner_legend',name:'Банер «Легенда»',desc:'Елітний банер для твоєї ігрової картки.',cost:250,art:'♜',rarity:'LEGENDARY',kind:'banner',value:'LEGEND'},
{id:'title_loot',name:'Король луту',desc:'Для тих, хто ніколи не виходить із матчу з порожніми руками.',cost:300,art:'♛',rarity:'LEGENDARY',kind:'title',value:'КОРОЛЬ ЛУТУ'},
{id:'badge_veteran',name:'Ветеран хабу',desc:'Пам’ятний знак активного гравця.',cost:100,art:'✪',rarity:'RARE',kind:'badge',value:'VETERAN'},
{id:'frame_steel',name:'Сталева рамка',desc:'Тактичне оформлення картки без зайвого блиску.',cost:90,art:'⬡',rarity:'COMMON',kind:'frame',value:'STEEL'},
{id:'title_raider',name:'Рейдер',desc:'Короткий бойовий титул для профілю.',cost:80,art:'⚑',rarity:'COMMON',kind:'title',value:'РЕЙДЕР'},
{id:'boost_xp',name:'XP-бустер +100',desc:'Одразу додай 100 XP та відкрий наступний рівень.',cost:110,art:'⚡',rarity:'EPIC',kind:'boost',value:'100 XP'},
{id:'supply_case',name:'Сезонний кейс',desc:'Випадкова косметична нагорода з колекції хабу.',cost:160,art:'▣',rarity:'EPIC',kind:'case',value:'MYSTERY'},
{id:'title_ace',name:'ACE мисливець',desc:'Титул для майстрів мініігор.',cost:220,art:'★',rarity:'LEGENDARY',kind:'title',value:'ACE МИСЛИВЕЦЬ'},
{id:'avatar_royal',name:'Аватар «Королівський шолом»',desc:'Аватар для профілю.',cost:190,art:'♛',rarity:'EPIC',kind:'avatar',value:'♛'},
{id:'avatar_phantom',name:'Аватар «Фантом»',desc:'Сезонний аватар для профілю.',cost:210,art:'☾',rarity:'EPIC',kind:'avatar',value:'☾'},
{id:'avatar_frost',name:'Аватар «Мороз»',desc:'Рідкісний аватар для профілю.',cost:220,art:'❄',rarity:'EPIC',kind:'avatar',value:'❄'},
{id:'avatar_commander',name:'Аватар «Командир»',desc:'Легендарний аватар для профілю.',cost:260,art:'♜',rarity:'LEGENDARY',kind:'avatar',value:'♜'},
{id:'frame_crimson',name:'Багряна рамка',desc:'Контрастна рамка для бойової картки.',cost:175,art:'▣',rarity:'EPIC',kind:'frame',value:'CRIMSON'},
{id:'title_pathfinder',name:'Слідопит',desc:'Для гравця, який завжди знає маршрут.',cost:135,art:'⌖',rarity:'RARE',kind:'title',value:'СЛІДОПИТ'},
{id:'badge_ace',name:'Знак ACE',desc:'Значок для майстра мініігор.',cost:280,art:'★',rarity:'LEGENDARY',kind:'badge',value:'ACE'},
{id:'theme_ice',name:'Крижана операція',desc:'Холодна тактична тема профілю.',cost:240,art:'❄',rarity:'EPIC',kind:'theme',value:'ICE'},
{id:'banner_ember',name:'Банер «Жар бою»',desc:'Вогняний банер для картки гравця.',cost:320,art:'🔥',rarity:'LEGENDARY',kind:'banner',value:'EMBER'},
{id:'avatar_recon',name:'Аватар «Розвідник»',desc:'Аватар для тих, хто діє непомітно.',cost:160,art:'⌖',rarity:'RARE',kind:'avatar',value:'⌖'}
