function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){}}
function level(){return Math.floor(state.xp/100)+1}
function showToast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>el.classList.remove('show'),2300)}
function addReward(coins,points,xp){state.coins+=coins;state.points+=points;addXP(xp);save();render()}
function ensureDailyMissions(){const today=localDateKey();if(state.dailyMissionDate!==today){state.dailyMissionDate=today;state.dailyMissionStartPlayed=state.played;state.dailyMissionClaims=[];save()}}
const dailyMissions=[{id:'daily_play1',title:'Розігрів загону',desc:'Зіграй 1 мінігру сьогодні',reward:20,xp:10,test:()=>state.played-state.dailyMissionStartPlayed>=1},{id:'daily_play3',title:'Без зупинки',desc:'Зіграй 3 мініігри сьогодні',reward:45,xp:20,test:()=>state.played-state.dailyMissionStartPlayed>=3},{id:'daily_drop',title:'Забезпечення прибуло',desc:'Забери щоденний дроп на головній',reward:15,xp:10,test:()=>state.dailyClaimDate===localDateKey()}];
function renderDailyMissions(){const el=$('#dailyMissions');if(!el)return;ensureDailyMissions();const doneCount=dailyMissions.filter(m=>state.dailyMissionClaims.includes(m.id)).length;const progress=$('#dailyMissionProgress');if(progress)progress.textContent=doneCount+' / '+dailyMissions.length+' ЗАБРАНО';el.innerHTML=dailyMissions.map(m=>{const ready=m.test(),claimed=state.dailyMissionClaims.includes(m.id);return '<article class="daily-mission-row '+(claimed?'done':'')+'"><div class="mission-check">'+(claimed?'✓':ready?'!':'◇')+'</div><div class="mission-copy"><b>'+m.title+'</b><small>'+m.desc+'</small><small class="daily-mission-reward">◈ +'+m.reward+' монет · ⚡ +'+m.xp+' XP</small></div><button type="button" class="daily-mission-claim" data-daily-claim="'+m.id+'" '+(!ready||claimed?'disabled':'')+'>'+(claimed?'ЗАБРАНО ✓':ready?'ЗАБРАТИ':'У ПРОЦЕСІ')+'</button></article>'}).join('')}
function renderMissions(){const make=m=>{const done=state.completed.includes(m.id);return '<div class="mission-row '+(done?'done':'')+'"><div class="mission-check">'+(done?'✓':'◇')+'</div><div class="mission-copy"><b>'+m.title+'</b><small>'+m.desc+'</small></div><div class="mission-reward">◈ +'+m.reward+'</div></div>'};$('#homeMissions').innerHTML=missions.slice(0,3).map(make).join('');$('#allMissions').innerHTML=missions.map(make).join('');$('#missionProgress').textContent=state.completed.length+' / '+missions.length+' ВИКОНАНО';renderDailyMissions()}
let shopFilter='all';function renderRewards(){$('#rewardBalance').textContent=state.coins;const count=$('#collectionCount');if(count)count.textContent='КОЛЕКЦІЯ: '+rewards.filter(r=>state.owned.includes(r.id)).length+' / '+rewards.filter(r=>r.kind!=='boost'&&r.kind!=='case').length;const visibleRewards=shopFilter==='all'?rewards:rewards.filter(r=>r.kind===shopFilter);$('#rewardsGrid').innerHTML=visibleRewards.map(r=>{const own=state.owned.includes(r.id),equipped=[state.equippedTitle,state.equippedFrame,state.equippedAvatar,state.equippedTheme,state.equippedBadge,state.equippedBanner].includes(r.id);let button;if(r.kind==='boost')button='<button data-buy="'+r.id+'">КУПИТИ</button>';else if(r.kind==='case')button='<button data-buy="'+r.id+'">ВІДКРИТИ</button>';else if(own)button='<button data-equip="'+r.id+'">'+(equipped?'ОБРАНО ✓':'ЕКІПІРУВАТИ')+'</button>';else button='<button data-buy="'+r.id+'">КУПИТИ</button>';return '<article class="reward-card rarity-'+r.rarity.toLowerCase()+'"><div class="reward-rarity">'+r.rarity+'</div><div class="reward-art">'+r.art+'</div><h3>'+r.name+'</h3><p>'+r.desc+'</p><div class="reward-buy"><b>◈ '+r.cost+'</b>'+button+'</div></article>'}).join('');const title=state.equippedTitle?rewards.find(r=>r.id===state.equippedTitle)?.value||'ГРАВЕЦЬ':'ГРАВЕЦЬ';const profileTitle=$('#profileTitle');if(profileTitle)profileTitle.textContent=title;const badge=$('#profileCosmeticBadge');if(badge)badge.textContent=state.equippedBadge?(rewards.find(r=>r.id===state.equippedBadge)?.value||'ACTIVE PLAYER'):'ACTIVE PLAYER';const avatarEl=$('#profileAvatar');if(avatarEl){const av=state.equippedAvatar?rewards.find(r=>r.id===state.equippedAvatar):null;avatarEl.textContent=av?(av.value||av.art):(state.name.trim()[0]||'K').toUpperCase();avatarEl.classList.toggle('cosmetic-avatar',!!av)}const card=$('.profile-card');if(card){card.classList.toggle('theme-gold',state.equippedTheme==='theme_gold');card.classList.toggle('frame-neon',state.equippedFrame==='frame_neon');card.classList.toggle('frame-steel',state.equippedFrame==='frame_steel');card.classList.toggle('banner-legend',state.equippedBanner==='banner_legend');card.classList.toggle('frame-crimson',state.equippedFrame==='frame_crimson');card.classList.toggle('theme-ice',state.equippedTheme==='theme_ice');card.classList.toggle('banner-ember',state.equippedBanner==='banner_ember')}}
function localDateKey(d=new Date()){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function dailyShopItems(){const pool=rewards.filter(r=>r.kind!=='boost'&&r.kind!=='case');const seed=Number(new Date().toISOString().slice(0,10).replace(/-/g,''));const n=pool.length;return [pool[seed%n],pool[(seed+5)%n],pool[(seed+11)%n]]}
function renderDailyShop(){const el=$('#dailyShopGrid');if(!el)return;el.innerHTML=dailyShopItems().map(r=>{const own=state.owned.includes(r.id),price=Math.max(10,Math.floor(r.cost*.75));return '<article class="daily-shop-item"><div class="daily-shop-art">'+r.art+'</div><div class="daily-shop-copy"><b>'+r.name+'</b><small>'+r.cost+' ◈ → <strong>'+price+' ◈</strong></small></div><button data-daily-buy="'+r.id+'" '+(own?'disabled':'')+'>'+(own?'Є В КОЛЕКЦІЇ':'КУПИТИ')+'</button></article>'}).join('')}
function renderSecretCode(){const input=$('#secretCodeInput'),button=$('#redeemSecretCode'),result=$('#secretCodeResult');if(!input||!button||!result)return;const day=localDateKey(),claimed=state.redeemedCodes.includes('daily-'+day),fixed=state.redeemedCodes.includes('KH2026');button.disabled=claimed;button.textContent=claimed?'КОД ДНЯ ВЖЕ АКТИВОВАНО ✓':'АКТИВУВАТИ КОД ↗';if(claimed){result.innerHTML='<b>Нагороду дня вже забрано.</b><small>Новий код з’явиться завтра.</small>'}else if(fixed){result.innerHTML='<b>Постійний код KH2026 вже використано.</b><small>Код дня ще можна активувати.</small>'}}
function redeemSecretCode(){if(getAuthToken()){showToast('Секретні коди поки доступні лише в локальному режимі. Онлайн-баланс не змінено.');return}const input=$('#secretCodeInput'),result=$('#secretCodeResult');if(!input||!result)return;const code=input.value.trim().toUpperCase(),day=localDateKey(),daily='KOZAK'+String(new Date().getDate()).padStart(2,'0');if(code===daily){if(state.redeemedCodes.includes('daily-'+day)){showToast('Код дня вже використано.');return}state.redeemedCodes.push('daily-'+day);state.coins+=30;state.points+=20;addXP(25);save();render();result.innerHTML='<b>Код прийнято! +30 монет · +20 очок · +25 XP</b><small>Повертайся завтра по новий код.</small>';showToast('Секретний код активовано!');input.value='';return}if(code==='KH2026'){if(state.redeemedCodes.includes('KH2026')){result.innerHTML='<b>Цей постійний код уже використано.</b>';return}state.redeemedCodes.push('KH2026');state.coins+=50;state.points+=30;addXP(40);save();render();result.innerHTML='<b>Постійний бонус: +50 монет · +30 очок · +40 XP</b><small>Дякую, що граєш у KH么Kozak Battle Hub!</small>';showToast('Бонус KH2026 активовано!');input.value='';return}result.innerHTML='<b>Код не розпізнано.</b><small>Перевір написання: KOZAK + число дня місяця або KH2026.</small>';showToast('Невірний код. Спробуй ще раз.')}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-daily-buy]');if(!b)return;const r=rewards.find(x=>x.id===b.dataset.dailyBuy);if(!r)return;if(getAuthToken()){try{const data=await apiRequest('/api/shop/purchase',{method:'POST',body:JSON.stringify({itemId:r.id,daily:true})});applyOnlineUser(data.user);const won=rewards.find(x=>x.id===data.wonItemId);renderDailyShop();showToast(data.wonItemId?'Магазин дня: кейс відкрив '+(won?.name||data.wonItemId):'Магазин дня: придбано '+r.name+' зі знижкою на сервері.')}catch(error){showToast(error.message)}return}if(state.owned.includes(r.id)){showToast('Цей предмет уже є в колекції.');renderDailyShop();return}const price=Math.max(10,Math.floor(r.cost*.75));if(state.coins<price){showToast('Не вистачає монет для магазину дня.');return}state.coins-=price;state.owned.push(r.id);state.dailyShopBuys=(state.dailyShopBuys||0)+1;const key={title:'equippedTitle',frame:'equippedFrame',avatar:'equippedAvatar',theme:'equippedTheme',badge:'equippedBadge',banner:'equippedBanner'}[r.kind];if(key)state[key]=r.id;save();render();showToast('Магазин дня: отримано '+r.name+' зі знижкою!')});
$('#redeemSecretCode')?.addEventListener('click',redeemSecretCode);$('#secretCodeInput')?.addEventListener('keydown',e=>{if(e.key==='Enter')redeemSecretCode()});
function renderDaily(){const today=localDateKey(),claimed=state.dailyClaimDate===today,button=$('#claimDaily');button.disabled=claimed;button.textContent=claimed?'ДРОП УЖЕ ЗАБРАН ✓':'ЗАБРАТИ ДРОП ↗';$('#dailyDropText').textContent=claimed?'Ти вже забрав сьогоднішнє постачання. Повертайся завтра!':'Забери щоденний бонус. Серія входів: '+(state.dailyStreak||0)+' дн.';document.querySelector('.daily-drop').classList.toggle('claimed',claimed)}
function render(){ensurePassSeason();const lv=level(),xp=state.xp%100;$('#coinTop').textContent=state.coins;$('#coinStat').textContent=state.coins;$('#pointsStat').textContent=state.points;$('#levelStat').textContent=lv;$('#xpLine').textContent=xp+' / 100 XP до наступного';$('#xpBar').style.width=xp+'%';$('#playedStat').textContent=state.played;$('#welcomeName').textContent=state.name;$('#profileName').textContent=state.name;$('#profileAvatar').textContent=state.equippedAvatar?(rewards.find(r=>r.id===state.equippedAvatar)?.value||'K'):(state.name.trim()[0]||'K').toUpperCase();$('#avatarMini').textContent=state.equippedAvatar?(rewards.find(r=>r.id===state.equippedAvatar)?.value||'K'):(state.name.trim()[0]||'K').toUpperCase();$('#profileLevel').textContent='LVL '+lv;$('#profilePlayed').textContent=state.played;$('#bestReaction').textContent=state.bestReaction===null?'—':state.bestReaction+' мс';$('#ownedRewards').textContent=state.owned.length;$('#nickname').value=state.name;renderMissions();renderRewards();renderDailyShop();renderDaily();renderPass();renderAssistantStats();renderAchievements();renderRank();renderSecretCode();renderOnlineStatus();checkMissions()}
function checkMissions(){if(getAuthToken())return;let changed=false;for(const m of missions){if(!state.completed.includes(m.id)&&m.test(state)){state.completed.push(m.id);state.coins+=m.reward;changed=true;showToast('Місію виконано: +'+m.reward+' монет!')}}if(changed){save();renderMissions();renderRewards();$('#coinTop').textContent=state.coins;$('#coinStat').textContent=state.coins}}
function goTab(tab){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id==='tab-'+tab));$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));window.scrollTo({top:0,behavior:'smooth'})}
$$('[data-tab]').forEach(b=>b.addEventListener('click',()=>goTab(b.dataset.tab)));$$('[data-tab-link]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();goTab(b.dataset.tabLink)}));$$('[data-go]').forEach(b=>b.addEventListener('click',()=>goTab(b.dataset.go)));
$('#claimDaily').addEventListener('click',()=>{if(getAuthToken()){showToast('Щоденний дроп браузера локальний. Для серверної нагороди в Telegram використовуй /daily.');return}const today=localDateKey();if(state.dailyClaimDate===today)return;const yesterday=localDateKey(new Date(Date.now()-86400000));state.dailyStreak=state.lastDailyDate===yesterday?(state.dailyStreak||0)+1:1;state.lastDailyDate=today;state.dailyClaimDate=today;state.coins+=25;state.points+=20;addXP(25);let bonus='';if(state.dailyStreak===3){state.coins+=50;state.points+=40;addXP(40);bonus=' Серія 3 дні: ще +50 монет і +40 XP!'}else if(state.dailyStreak===7){state.coins+=150;state.points+=100;addXP(100);bonus=' Серія 7 днів: ще +150 монет і +100 XP!'}save();render();showToast('Щоденний дроп отримано: +25 монет!'+bonus)});
$('#saveNick').addEventListener('click',()=>{if(getAuthToken()){ $('#saveMsg').textContent='Зміна ніка онлайн-акаунта ще не підключена. Локально не змінюю серверний профіль.';return}const n=$('#nickname').value.trim();if(!n){$('#saveMsg').textContent='Введи нік перед збереженням.';return}state.name=n;save();render();$('#saveMsg').textContent='Профіль збережено на цьому пристрої.';showToast('Профіль оновлено')});
$('#resetProgress').addEventListener('click',()=>{if(getAuthToken()){showToast('Скидання доступне лише для локального профілю. Онлайн-акаунт не змінено.');return}if(confirm('Скинути монети, очки, місії та статистику на цьому пристрої?')){state={...defaultState,owned:[],completed:[],games:{...defaultState.games}};save();render();$('#saveMsg').textContent='Локальний прогрес скинуто.';showToast('Прогрес скинуто')}});
$('#shopFilters').addEventListener('click',e=>{const b=e.target.closest('[data-shop-filter]');if(!b)return;shopFilter=b.dataset.shopFilter;$$('[data-shop-filter]').forEach(x=>x.classList.toggle('active',x===b));renderRewards()});$('#rewardsGrid').addEventListener('click',async e=>{const equip=e.target.closest('[data-equip]');if(equip){const r=rewards.find(x=>x.id===equip.dataset.equip);if(!r||!state.owned.includes(r.id))return;if(getAuthToken()){try{const data=await apiRequest('/api/shop/equip',{method:'POST',body:JSON.stringify({itemId:r.id})});applyOnlineUser(data.user);showToast('Екіпірування збережено на сервері.')}catch(error){showToast(error.message)}return}const key={title:'equippedTitle',frame:'equippedFrame',avatar:'equippedAvatar',theme:'equippedTheme',badge:'equippedBadge',banner:'equippedBanner'}[r.kind];if(!key)return;state[key]=state[key]===r.id?'':r.id;save();render();showToast(state[key]?'Предмет екіпіровано!':'Предмет знято');return}const b=e.target.closest('[data-buy]');if(!b)return;const r=rewards.find(x=>x.id===b.dataset.buy);if(!r)return;if(getAuthToken()){try{const data=await apiRequest('/api/shop/purchase',{method:'POST',body:JSON.stringify({itemId:r.id,daily:false})});applyOnlineUser(data.user);const won=rewards.find(x=>x.id===data.wonItemId);showToast(data.wonItemId?'Кейс: '+(won?.name||data.wonItemId)+' — збережено на сервері.':data.itemKind==='boost'?'XP-бустер придбано на сервері.':'Придбано '+r.name+' на сервері.');}catch(error){showToast(error.message)}return}if(r.kind!=='boost'&&r.kind!=='case'&&state.owned.includes(r.id))return;if(state.coins<r.cost){showToast('Не вистачає монет. Зіграй ще кілька мініігор!');return}state.coins-=r.cost;if(r.kind==='boost'){addXP(100);save();render();showToast('XP-бустер активовано: +100 XP!');return}if(r.kind==='case'){const pool=rewards.filter(x=>['title','frame','avatar','theme','badge','banner'].includes(x.kind)&&!state.owned.includes(x.id));if(!pool.length){state.coins+=r.cost;showToast('Ти вже зібрав усю колекцію! Монети повернуто.');save();render();return}const won=pool[Math.floor(Math.random()*pool.length)];state.owned.push(won.id);state.caseOpens=(state.caseOpens||0)+1;const wonKey={title:'equippedTitle',frame:'equippedFrame',avatar:'equippedAvatar',theme:'equippedTheme',badge:'equippedBadge',banner:'equippedBanner'}[won.kind];if(wonKey)state[wonKey]=won.id;save();render();showToast('У кейсі: '+won.name+'!');return}state.owned.push(r.id);const key={title:'equippedTitle',frame:'equippedFrame',avatar:'equippedAvatar',theme:'equippedTheme',badge:'equippedBadge',banner:'equippedBanner'}[r.kind];if(key)state[key]=r.id;save();render();showToast('Отримано '+r.name+'! Предмет екіпіровано.')});
const modal=$('#gameModal'),area=$('#gameArea'),message=$('#gameMessage'),title=$('#modalTitle'),desc=$('#modalDesc'),eyebrow=$('#modalEyebrow');let cleanups=[];

const AUTH_TOKEN_KEY='khkozak_online_token_v1',REFRESH_TOKEN_KEY='khkozak_supabase_refresh_v1',API_BASE_KEY='khkozak_api_base',SUPABASE_KEY_STORAGE='khkozak_supabase_anon_key';
const DEFAULT_SUPABASE_URL='https://xacqretciujzrcqjvvgz.supabase.co';
const DEFAULT_SUPABASE_PUBLIC_KEY='sb_publishable_ddFWdvi_fwHWSft0WzfXYg_Oxc8dm1O';
function apiBase(){const saved=localStorage.getItem(API_BASE_KEY)||'',meta=document.querySelector('meta[name="kh-api-base"]')?.content||'';return (saved||meta||DEFAULT_SUPABASE_URL).trim().replace(/\/$/,'')}
function supabasePublicKey(){return localStorage.getItem(SUPABASE_KEY_STORAGE)||DEFAULT_SUPABASE_PUBLIC_KEY}
function getAuthToken(){try{return localStorage.getItem(AUTH_TOKEN_KEY)||''}catch{return ''}}
function setOnlineMessage(text,isError=false){const el=$('#onlineAccountMessage');if(el){el.textContent=text;el.classList.toggle('error',!!isError)}}
async function apiRequest(path,options={},didRefresh=false){const base=apiBase(),publicKey=supabasePublicKey();if(!base)throw new Error('Введи URL свого проєкту Supabase.');if(!publicKey)throw new Error('Введи публічний ключ Supabase (publishable/anon).');if(!/^https:\/\/[a-z0-9-]+\.supabase\.co$/i.test(base))throw new Error('Введи URL проєкту у форматі https://project-ref.supabase.co');const headers={'Content-Type':'application/json','apikey':publicKey,...(options.headers||{})};const token=getAuthToken();if(token)headers.Authorization='Bearer '+token;let response;try{response=await fetch(base+'/functions/v1/hub-api'+path,{...options,headers})}catch{throw new Error('Не вдалося з’єднатися із Supabase. Перевір URL і мережу.')}const data=await response.json().catch(()=>({}));if(response.status===401&&token&&!didRefresh&&localStorage.getItem(REFRESH_TOKEN_KEY)){try{await refreshSupabaseSession();return await apiRequest(path,options,true)}catch{localStorage.removeItem(AUTH_TOKEN_KEY);localStorage.removeItem(REFRESH_TOKEN_KEY)}}if(!response.ok){const error=new Error(data.error||('HTTP '+response.status));error.status=response.status;throw error}return data}
function applyOnlineUser(user){if(!user)return;if(!localStorage.getItem('khkozak_hub_v6_offline_backup')){try{localStorage.setItem('khkozak_hub_v6_offline_backup',JSON.stringify(state))}catch{}}state.name=user.username||state.name;state.coins=Number(user.coins)||0;state.points=Number(user.points)||0;state.xp=Number(user.xp)||0;state.played=Number(user.played)||0;state.games={...defaultState.games,...(user.games||{})};if(Array.isArray(user.inventory))state.owned=user.inventory.slice();if(Array.isArray(user.achievements))state.serverAchievements=user.achievements.slice();state.equippedTitle=user.equipped_title||'';state.equippedFrame=user.equipped_frame||'';state.equippedAvatar=user.equipped_avatar||'';state.equippedTheme=user.equipped_theme||'';state.equippedBadge=user.equipped_badge||'';state.equippedBanner=user.equipped_banner||'';save();render()}
function renderOnlineStatus(){const pill=$('#onlineStatusPill'),logout=$('#onlineLogout'),register=$('#onlineRegister'),login=$('#onlineLogin');if(!pill)return;const connected=!!apiBase(),signed=!!getAuthToken();pill.textContent=signed?'АКАУНТ ОНЛАЙН':connected?'СЕРВЕР НАЛАШТОВАН':'НЕ ПІДКЛЮЧЕНО';pill.classList.toggle('online-ready',connected&&signed);if(logout)logout.hidden=!signed;if(register)register.disabled=signed;if(login)login.disabled=signed;const url=$('#onlineApiUrl');if(url&&document.activeElement!==url)url.value=apiBase();const keyInput=$('#onlineSupabaseKey');if(keyInput&&document.activeElement!==keyInput)keyInput.value=supabasePublicKey()}
async function connectOnlineApi(){const field=$('#onlineApiUrl'),keyField=$('#onlineSupabaseKey'),base=(field?.value||'').trim().replace(/\/$/,'');const publicKey=(keyField?.value||'').trim();if(!/^https:\/\/[a-z0-9-]+\.supabase\.co$/i.test(base)){setOnlineMessage('Введи URL Supabase у форматі https://project-ref.supabase.co',true);return}if(!publicKey){setOnlineMessage('Встав публічний publishable/anon key із Supabase → Project Settings → API.',true);return}try{localStorage.setItem(API_BASE_KEY,base);localStorage.setItem(SUPABASE_KEY_STORAGE,publicKey);const data=await apiRequest('/api/health');if(!data.ok||data.database!=='connected')throw new Error(data.error||'База даних не підключена. Запусти supabase/schema.sql та розгорни Edge Function.');renderOnlineStatus();setOnlineMessage('Supabase і база даних підключені. Тепер можна створити акаунт або увійти.');await loadLeaderboard()}catch(error){renderOnlineStatus();setOnlineMessage(error.message,true)}}
async function authenticateOnline(mode){const email=$('#onlineEmail')?.value.trim(),password=$('#onlinePassword')?.value||'',username=$('#onlineNickname')?.value.trim()||state.name;if(!email||!password){setOnlineMessage('Заповни електронну пошту та пароль.',true);return}if(mode==='register'&&username.length<3){setOnlineMessage('Ігровий нік має містити щонайменше 3 символи.',true);return}const buttons=[$('#onlineRegister'),$('#onlineLogin')].filter(Boolean);buttons.forEach(b=>b.disabled=true);setOnlineMessage(mode==='register'?'Створюю акаунт у Supabase…':'Виконую вхід…');try{const data=await apiRequest('/api/auth/'+mode,{method:'POST',body:JSON.stringify({email,password,username})});if(data.confirmationRequired){setOnlineMessage(data.message||'Перевір пошту та підтвердь адресу, потім увійди.');return}if(!data.token)throw new Error('Supabase не повернув сесію. Перевір налаштування Auth і підтвердження email.');localStorage.setItem(AUTH_TOKEN_KEY,data.token);if(data.refreshToken)localStorage.setItem(REFRESH_TOKEN_KEY,data.refreshToken);applyOnlineUser(data.user);renderOnlineStatus();setOnlineMessage('Готово! Акаунт '+data.user.username+' підключено. Онлайн-прогрес зберігається в Supabase.');await loadLeaderboard();await loadTelegramStatus();await refreshAdminData();showToast(mode==='register'?'Акаунт створено!':'Вхід виконано!')}catch(error){setOnlineMessage(error.message,true)}finally{renderOnlineStatus()}}
async function refreshSupabaseSession(){const base=apiBase(),publicKey=supabasePublicKey(),refreshToken=localStorage.getItem(REFRESH_TOKEN_KEY);if(!base||!publicKey||!refreshToken)throw new Error('Сесія завершилася. Увійди знову.');const response=await fetch(base+'/functions/v1/hub-api/api/auth/refresh',{method:'POST',headers:{'Content-Type':'application/json','apikey':publicKey},body:JSON.stringify({refreshToken})});const data=await response.json().catch(()=>({}));if(!response.ok||!data.token)throw new Error(data.error||'Не вдалося оновити сесію.');localStorage.setItem(AUTH_TOKEN_KEY,data.token);if(data.refreshToken)localStorage.setItem(REFRESH_TOKEN_KEY,data.refreshToken);return data}
async function refreshOnlineAccount(){if(!getAuthToken()||!apiBase())return;try{const data=await apiRequest('/api/auth/me');applyOnlineUser(data.user);renderOnlineStatus()}catch(error){if(error.status===401){localStorage.removeItem(AUTH_TOKEN_KEY);localStorage.removeItem(REFRESH_TOKEN_KEY);renderOnlineStatus();setOnlineMessage('Сесія завершилася. Увійди знову.',true)}}}
async function finishOnlineGame(game){const eventId=globalThis.crypto?.randomUUID?crypto.randomUUID():'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&3|8)).toString(16)});try{const data=await apiRequest('/api/games/finish',{method:'POST',body:JSON.stringify({game,eventId})});await loadLeaderboard();return{ok:true,data}}catch(error){if(error.status&&error.status!==0)return{ok:false,serverError:true,error:error.message};return{ok:false,serverError:false,error:error.message}}}
async function loadLeaderboard(){const el=$('#onlineLeaderboard');if(!el||!apiBase())return;try{const data=await apiRequest('/api/leaderboard?limit=10',{method:'GET'});if(!data.leaderboard?.length){el.innerHTML='<p class="online-empty">Поки немає гравців. Створи акаунт і стань першим!</p>';return}el.innerHTML=data.leaderboard.map(p=>'<div class="online-player"><span class="online-place">#'+p.rank+'</span><b>'+escapeOnlineText(p.username)+'</b><span>'+Number(p.points).toLocaleString('uk-UA')+' очок</span></div>').join('')}catch(error){el.innerHTML='<p class="online-empty">'+escapeOnlineText(error.message)+'</p>'}}
function escapeOnlineText(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
$('#connectOnlineApi')?.addEventListener('click',connectOnlineApi);
$('#onlineRegister')?.addEventListener('click',()=>authenticateOnline('register'));
$('#onlineLogin')?.addEventListener('click',()=>authenticateOnline('login'));
$('#onlineLogout')?.addEventListener('click',()=>{localStorage.removeItem(AUTH_TOKEN_KEY);localStorage.removeItem(REFRESH_TOKEN_KEY);renderOnlineStatus();setOnlineMessage('Ти вийшов з онлайн-акаунта. Локальний прогрес на пристрої не видалено.');loadTelegramStatus();refreshAdminData();showToast('Вихід виконано')});
$('#refreshLeaderboard')?.addEventListener('click',loadLeaderboard);
$('#onlinePassword')?.addEventListener('keydown',e=>{if(e.key==='Enter')authenticateOnline('login')});
if($('#onlineNickname'))$('#onlineNickname').value=state.name||'KH么Kozak';
renderOnlineStatus();
if(getAuthToken()&&apiBase())refreshOnlineAccount();
if(apiBase())loadLeaderboard();

function cleanup(){cleanups.forEach(f=>{try{f()}catch(e){}});cleanups=[]}
function openModal(type){cleanup();modal.classList.add('open');modal.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';message.textContent='';area.innerHTML='';if(type==='reaction')startReaction();if(type==='aim')startAim();if(type==='quiz')startQuiz();if(type==='memory')startMemory();if(type==='loot')startLoot();if(type==='pubg')startPubg();if(type==='arena')startArena();if(type==='classic')startClassic();if(type==='metro')startMetro();if(type.startsWith('arcade-'))startArcadeGame(type.slice(7))}
function closeModal(){cleanup();modal.classList.remove('open');modal.setAttribute('aria-hidden','true');document.body.style.overflow='';}
$('#closeModal').addEventListener('click',closeModal);modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
$$('[data-game]').forEach(b=>b.addEventListener('click',()=>openModal(b.dataset.game)));
function finishGame(kind,coins,points,xp){
 const again=document.createElement('button');again.className='game-start';again.textContent='ЗІГРАТИ ЩЕ';again.addEventListener('click',()=>openModal(kind));
 if(getAuthToken()&&apiBase()){
  message.textContent='Перевіряю результат на сервері…';
  finishOnlineGame(kind).then(result=>{
   if(result?.ok){applyOnlineUser(result.data.user);message.textContent='Онлайн-нагорода: +'+result.data.reward.coins+' монет · +'+result.data.reward.points+' очок · +'+result.data.reward.xp+' XP'+(result.data.dailyBonus?' — бонус першої гри дня включено':'');if(result.data.dailyBonus)showToast('Онлайн-бонус дня отримано!');else showToast('Онлайн-нагороду збережено!')}
   else if(result?.serverError){message.textContent=result.error||'Сервер відхилив результат. Онлайн-баланс не змінено.';showToast('Онлайн-нагороду не зараховано.')}
   else {message.textContent='Сервер недоступний — онлайн-нагороду не зараховано. Перевір з’єднання та спробуй ще раз.';showToast('Нагороду не зараховано: сервер недоступний.')}
   area.appendChild(again);
  });
  return;
 }
 awardLocalGame(kind,coins,points,xp);area.appendChild(again)
}
function awardLocalGame(kind,coins,points,xp){state.played++;state.games[kind]=(state.games[kind]||0)+1;const dailyBonus=state.dailyGameBonusDate!==localDateKey();if(dailyBonus){state.dailyGameBonusDate=localDateKey();state.coins+=15;state.points+=10;addXP(10)}addReward(coins,points,xp);message.textContent='Нагорода: +'+coins+' монет · +'+points+' очок · +'+xp+' XP'+(dailyBonus?' — бонус першої гри дня: +15 монет · +10 очок · +10 XP':'');if(dailyBonus)showToast('Перша гра дня: бонус +15 монет, +10 очок і +10 XP!')}


