 const sets=questionSets[id]||[[g.name,['Обрати тактику','Поспішити','Ігнорувати ситуацію'],0,'Чудово!'],['Наступний крок?',['Перевірити укриття','Бігти відкрито','Зупинитися'],0,'Тактика працює.'],['Фінальне рішення?',['Допомогти загону','Розбігтися','Забути про зону'],0,'Раунд завершено.']];
 const draw=()=>{if(done)return;if(round>=sets.length){finish();return}const q=sets[round];box.innerHTML='<div class="arcade-progress">РАУНД '+(round+1)+' / '+sets.length+' · ОЧКИ '+score+'</div><h3>'+q[0]+'</h3>';const opts=q[1].slice();opts.forEach((label,i)=>{const b=btn(label,()=>{if(done)return;const correct=i===q[2];if(correct)score++;message.textContent=(correct?'✓ ':'✕ ')+q[3];round++;setTimeout(draw,500)},'arcade-option');});};
