 if(id==='reload'||id==='grenade'){box.innerHTML='<h3>ЗУПИНИ ІНДИКАТОР У ЗЕЛЕНІЙ ЗОНІ</h3><div class="timing-track"><i id="timingMarker"></i><b></b></div>';const track=box.querySelector('.timing-track'),marker=box.querySelector('#timingMarker');let pos=0,dir=1;const interval=setInterval(()=>{pos+=dir*3.2;if(pos>96||pos<0)dir*=-1;marker.style.left=pos+'%'},35);cleanups.push(()=>clearInterval(interval));btn('ЗУПИНИ!',()=>{clearInterval(interval);score=Math.abs(pos-50)<17?3:Math.abs(pos-50)<32?2:1;round=3;box.innerHTML='<h3>'+ (score===3?'ІДЕАЛЬНИЙ ТАЙМІНГ!':score===2?'НЕПОГАНО!':'ЩЕ ТРЕНУЙСЯ!')+'</h3><p>Точність: '+score+'/3</p>';btn('ЗАВЕРШИТИ',finish,'arcade-option')},'arcade-option');return}
