function renderPass(){ensurePassSeason();const lv=passLevel(),xp=(state.passXp||0)%100;const l=$('#passLevel'),x=$('#passXp'),bar=$('#passXpBar'),track=$('#passTrack');if(!l||!track)return;const theme=seasonThemes[new Date().getMonth()]||seasonThemes[0];const seasonLabel=$('#passSeasonName');if(seasonLabel)seasonLabel.textContent=theme.title.toUpperCase()+' / '+currentSeasonKey();const passTitle=$('#passHeroTitle');if(passTitle)passTitle.textContent=theme.title.toUpperCase();l.textContent=String(Math.min(lv,20)).padStart(2,'0');x.textContent=xp+' / 100 XP';bar.style.width=xp+'%';const monthlyRewards=passRewards.slice();monthlyRewards[19]={...passRewards[19],name:theme.rewardName,desc:'Аватар місяця — отримай та екіпіруй у профілі.',icon:theme.icon,item:theme.avatarId};track.innerHTML=monthlyRewards.map((r,i)=>{const num=i+1,unlocked=lv>=num,claimed=state.passClaimed.includes(num);return '<article class="pass-reward '+(unlocked?'unlocked ':'')+(claimed?'claimed':'')+'"><span class="pass-number">РІВЕНЬ '+String(num).padStart(2,'0')+'</span><div class="pass-art">'+r.icon+'</div><h3>'+r.name+'</h3><p>'+r.desc+'</p><small class="pass-status">'+(claimed?'Нагороду забрано':unlocked?'Доступно для отримання':'Потрібно '+num+' рівень')+'</small><button data-pass-claim="'+num+'" '+(!unlocked||claimed?'disabled':'')+'>'+(claimed?'✓ ЗАБРАНО':unlocked?'ЗАБРАТИ НАГОРОДУ':'ЗАКРИТО')+'</button></article>'}).join('')}
