async function loadTelegramStatus(){
 const pill=$('#telegramLinkStatus'),msg=$('#telegramLinkMsg');if(!pill)return;
 if(!getAuthToken()){pill.textContent='ПОТРІБЕН ВХІД';if(msg)msg.textContent='Увійди в онлайн-акаунт у вкладці «Профіль», щоб прив’язати Telegram.';return}
 try{
  const data=await apiRequest('/api/telegram/status');
  pill.textContent=data.linked?'ПРИВ’ЯЗАНО ✓':'НЕ ПРИВ’ЯЗАНО';
  pill.classList.toggle('online-ready',!!data.linked);
  if(msg)msg.textContent=data.linked?'Telegram '+(data.username?'@'+data.username:'акаунт')+' прив’язано. Команди /profile, /daily і /top доступні.':(data.botConfigured?'Створи одноразовий код нижче та надішли боту /link КОД.':'Backend API доступний, але токен бота або секрет webhook ще не налаштовано на сервері.');
 }catch(error){pill.textContent='НЕ ПЕРЕВІРЕНО';if(msg)msg.textContent=error.message}
}
$('#createTelegramLink')?.addEventListener('click',async()=>{
 const button=$('#createTelegramLink'),codeBox=$('#telegramLinkCode'),msg=$('#telegramLinkMsg');
 button.disabled=true;button.textContent='СТВОРЮЮ КОД…';
 try{
  const data=await apiRequest('/api/telegram/link-code',{method:'POST',body:JSON.stringify({})});
  codeBox.hidden=false;codeBox.innerHTML='<strong>'+data.code+'</strong><small>Діє 10 хвилин. Відкрий бота й надішли: <b>/link '+data.code+'</b></small><button type="button" class="btn btn-ghost" id="copyTelegramCode">СКОПІЮВАТИ КОД</button>';
  $('#copyTelegramCode')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText('/link '+data.code);showToast('Команду зв’язування скопійовано')}catch{showToast('Введи команду вручну: /link '+data.code)}});
  msg.textContent=data.botConfigured?'Код створено на сервері. Не публікуй його: він одноразовий.':'Код створено, але серверний Telegram Bot Token/Webhook Secret ще не налаштовані.';
 }catch(error){msg.textContent=error.message}
 finally{button.disabled=false;button.textContent='СТВОРИТИ КОД ЗВ’ЯЗУВАННЯ'}
});
async function refreshAdminData(){
 const nav=$('#adminNav'),mobileNav=$('#adminMobileNav');if(!nav||!getAuthToken()){if(nav)nav.hidden=true;if(mobileNav)mobileNav.hidden=true;return}
 try{
  const data=await apiRequest('/api/admin/overview');nav.hidden=false;if(mobileNav)mobileNav.hidden=false;
  $('#adminProfiles').textContent=data.profiles;$('#adminLinks').textContent=data.linkedTelegram;$('#adminEvents').textContent=data.gameEvents;
  const recent=$('#adminRecentPlayers');if(recent)recent.innerHTML=(data.recentPlayers||[]).map(p=>'<div class="online-player"><span class="online-place">●</span><b>'+String(p.username||'Player').replace(/[<>]/g,'')+'</b><span>'+Number(p.points||0)+' очок · '+Number(p.played||0)+' ігор</span></div>').join('')||'<p class="online-empty">Профілів поки немає.</p>';
 }catch(error){nav.hidden=true;if(mobileNav)mobileNav.hidden=true;if(error.status&&error.status!==403)console.warn('Admin panel unavailable:',error.message)}
}
