$('#checkInstall')?.addEventListener('click',async()=>{
 const out=$('#installCheckResult');out.textContent='Перевіряю manifest і service worker…';
 const standalone=window.matchMedia?.('(display-mode: standalone)').matches||window.navigator.standalone===true;
 const secure=window.isSecureContext;
 let manifestOk=false,swOk=false,manifestDisplay='невідомо',swState='не підтримується';
 try{const link=document.querySelector('link[rel="manifest"]');if(link){const r=await fetch(link.href,{cache:'no-store'});if(r.ok){const m=await r.json();manifestOk=!!(m.name&&m.start_url&&Array.isArray(m.icons)&&m.icons.length);manifestDisplay=m.display||'не задано'}}}catch{}
 try{if('serviceWorker' in navigator){const reg=await navigator.serviceWorker.getRegistration('./');swOk=!!(reg&&(reg.active||reg.waiting||reg.installing));swState=reg?.active?'активний':reg?.waiting?'очікує активації':reg?.installing?'встановлюється':'не зареєстрований'}}catch{}
 const installPrompt=!!window.pwaPrompt||('onbeforeinstallprompt' in window);
 out.innerHTML='<b>'+(standalone?'ЗАПУЩЕНО ЯК ДОДАТОК':'ВІДКРИТО В БРАУЗЕРІ')+'</b><span>HTTPS: '+(secure?'так':'ні')+'</span><span>Manifest: '+(manifestOk?'OK':'не підтверджено')+' · display: '+manifestDisplay+'</span><span>Service worker: '+(swOk?'OK':'не підтверджено')+' ('+swState+')</span><span>Подія встановлення: '+(installPrompt?'підтримується браузером':'може не підтримуватися в цьому браузері')+'</span><small>'+(standalone?'Застосунок уже відкритий у встановленому режимі на цьому пристрої.':'Якщо HTTPS, manifest і service worker справні, відкрий меню браузера та вибери «Установити додаток». Цей тест не може підтвердити встановлення на іншому пристрої.')+'</small>';
});

function assistantReply(raw){const q=raw.toLowerCase();if(/челендж|виклик|challenge|рандом/.test(q)){const challenges=['Наступний матч: тільки лут із першого будинку. Так, навіть якщо там лише сковорідка 😅','Режим тихого ніндзя: не стріляй першим, доки не зміниш позицію.','Лут-детектив: знайди аптечку й приціл до першої серйозної перестрілки.','Командний режим: кожні 2 хвилини перевіряй, чи загін ще з тобою. Не губи своїх ботанів 🤝','Хардкор: після кожного нокауту міняй позицію. Стояти на місці — це запрошення в лобі.'];return '🎯 Челендж від напарника KH: '+challenges[Math.floor(Math.random()*challenges.length)]+' Напиши «ще челендж», якщо хочеш новий.'}if(/сьогод|щоденн|daily|місії|місія/.test(q))return '📋 План на сьогодні: зіграй одну мінігру для розігріву, зроби три катки в хабі та забери щоденний дроп на головній. У вкладці «Місії» можна окремо забрати монети й XP за виконані щоденні завдання. Не забудь забрати нагороду кнопкою — я не телепат, поки що 😎';if(/рів|level|xp|battle pass|пас/.test(q))return '⚡ План прокачки: забери дроп, виконай щоденні місії й зіграй у мініігри. Кожні 100 XP — новий рівень. Порадник не фармить за тебе, командире, але маршрут підкаже 😄';if(/монет|coin|зароб|баланс/.test(q))return '💰 Монети приходять за мініігри, щоденний дроп і місії. Зайди в «Місії», забери нагороди, а тоді заглянь у магазин. Не витрачай усе на блискучу рамку заради понтів… хоча виглядати легендою теж треба 😏';if(/мінігр|грат|ігри|game/.test(q))return '🎮 У хабі є тест реакції, тренування прицілу, PUBG Quiz, «Код доступу» на пам’ять та «Полювання за лутом» — і ще інші режими у вкладці «Ігри та режими». Розігрій пальці, чемпіоне!';if(/telegram|телеграм|бот/.test(q))return '📡 У вкладці Telegram дивись налаштування прив’язки акаунта. Якщо сервер і бот налаштовані, можна зв’язати профіль кодом та користуватися командами. Я не бачу секретів і не можу вдавати, що бот підключений, якщо сервер ще не налаштовано.';if(/профіл|статист|нік|xp|ранг/.test(q))return '🪪 У «Моєму профілі» є твоя картка, ранг, статистика й нагороди. Тепер також показуємо XP, серію щоденних входів і прогрес щоденних місій. Зміни нік, екіпіруй титул і виходь у бій стильно.';if(/допом|привіт|hello|hi|хто ти/.test(q))return 'Йо, боєць! Я KH — твій напарник по хабу: трохи тактик, трохи клоун загону, але без луту не залишу 😎 Запитай про монети, XP, місії або напиши «челендж». Поки я працюю локально; для справжніх відповідей зовнішньої ІІ-моделі потрібен захищений сервер.';return 'Так, командире 😎 Я ще в локальному режимі, але вже знаюся на місіях, монетах, XP, мінііграх і профілі. Спробуй: «що робити сьогодні?», «як заробити монети?» або «дай челендж». Для вільної розмови як у справжнього AI треба підключити захищений сервер.'} 
function getAssistantApiBase(){const field=$('#khApiBase');let saved='';try{saved=localStorage.getItem('kh_assistant_api_base')||''}catch{}return (field?.value||saved||document.querySelector('meta[name="kh-api-base"]')?.content||'').trim().replace(/[/]$/,'')}
function setAssistantStatus(message,connected=false){const status=$('#assistantConnectionStatus');if(status){status.textContent=message;status.classList.toggle('is-connected',connected)}}
function saveAssistantApiBase(){const field=$('#khApiBase');const value=(field?.value||'').trim().replace(/[/]$/,'');if(value){try{const url=new URL(value);if(url.protocol!=='https:'&&url.hostname!=='localhost'&&url.hostname!=='127.0.0.1'){showToast('Для публічного AI-сервера потрібен HTTPS.');return}localStorage.setItem('kh_assistant_api_base',value)}catch{showToast('Вкажи коректну адресу сервера, наприклад https://твій-сервер.example');return}}else{try{localStorage.removeItem('kh_assistant_api_base')}catch{}}
setAssistantStatus(value?'Адресу збережено · ще не перевірено':'Локальний режим · сервер не вказано',false);showToast(value?'Адресу AI-сервера збережено на цьому пристрої.':'Повернуто локальний режим.')}
async function testAssistantConnection(){const base=getAssistantApiBase();if(!base){setAssistantStatus('Локальний режим · сервер не вказано',false);showToast('Спочатку введи адресу свого AI-backend.');return}setAssistantStatus('Перевіряю зв’язок…',false);try{const response=await fetch(base+'/health',{method:'GET',headers:{'Accept':'application/json'}});if(!response.ok)throw new Error('HTTP '+response.status);const data=await response.json().catch(()=>({}));setAssistantStatus('Сервер відповідає'+(data.service?' · '+data.service:''),true);showToast('Зв’язок із сервером працює.')}catch(error){setAssistantStatus('Не вдалося перевірити /health · перевір URL і CORS',false);showToast('Немає відповіді від /health. Це не означає, що AI підключено.')} }
async function sendAssistant(text){const box=$('#assistantMessages');if(!box||!text.trim())return;const user=document.createElement('div');user.className='assistant-bubble user-bubble';user.textContent=text.trim();box.appendChild(user);const reply=document.createElement('div');reply.className='assistant-bubble bot-bubble';const apiBase=getAssistantApiBase();reply.textContent=apiBase?'Зачекай, отримую відповідь…':assistantReply(text);box.appendChild(reply);box.scrollTop=box.scrollHeight;if(apiBase){try{const response=await fetch(apiBase+'/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:text.trim()})});const data=await response.json();if(!response.ok)throw new Error(data.error||'API request failed');reply.textContent=data.reply||'Сервер не повернув відповідь.';setAssistantStatus('AI-backend відповів на запит',true)}catch(err){reply.textContent='Не вдалося підключитися до AI-сервера. Перевір адресу, маршрут /api/chat і CORS. Локальна підказка: '+assistantReply(text);setAssistantStatus('AI-сервер недоступний · показую локальну підказку',false)}box.scrollTop=box.scrollHeight}}
if($('#assistantForm'))$('#assistantForm').addEventListener('submit',e=>{e.preventDefault();const input=$('#assistantInput'),value=input.value.trim();if(!value)return;sendAssistant(value);input.value=''});
const apiBaseField=$('#khApiBase');if(apiBaseField){try{apiBaseField.value=localStorage.getItem('kh_assistant_api_base')||document.querySelector('meta[name="kh-api-base"]')?.content||''}catch{}setAssistantStatus(apiBaseField.value?'Адресу збережено · ще не перевірено':'Локальний режим · сервер не вказано',false)}
$('#saveAssistantApiBase')?.addEventListener('click',saveAssistantApiBase);
$('#testAssistantApiBase')?.addEventListener('click',testAssistantConnection);
$('#dailyMissions')?.addEventListener('click',e=>{const b=e.target.closest('[data-daily-claim]');if(!b)return;if(getAuthToken()){showToast('Щоденні місії поки змінюють лише локальний прогрес. Онлайн-баланс не змінено.');return}ensureDailyMissions();const m=dailyMissions.find(x=>x.id===b.dataset.dailyClaim);if(!m||state.dailyMissionClaims.includes(m.id)||!m.test())return;state.dailyMissionClaims.push(m.id);state.coins+=m.reward;state.points+=Math.ceil(m.reward/2);addXP(m.xp);save();render();showToast('Місію забрано: +'+m.reward+' монет і +'+m.xp+' XP!')});
